# Anti-pattern data, part C: visual presentation, media and motion, dynamic updates.
from data_a import R, S, X

VISUAL = [
 dict(id='AP-VIS-01', title='Low-contrast text', sev='major', wcag=['1.4.3'], rgaa=['3.2'], axe=['color-contrast'], lang='css',
  what='Light grey on white, white on a pastel button, text on a photo: the words fade for people with low vision, on a cheap screen or in daylight. Placeholders, captions, footers and disabled-looking links are the usual cases.',
  dtext='computed contrast between text and background under 4.5:1 (3:1 for large text). The regular expression only flags light greys used as a text colour; a checker must compute the ratio on the rendered page, and a person must check text on images and gradients.',
  detect=[X('Compute the WCAG contrast ratio of each text node against its effective background; report under 4.5:1, or under 3:1 for text of at least 24px or 18.5px bold.'),
          R(r'''(?:^|[;{\s])color\s*:\s*#(?:9{3}|a{3}|b{3}|c{3}|d{3}|e{3}|9{6}|a{6}|b{6}|c{6}|d{6}|e{6})\b''', target='css')],
  bad='.hint { color: #aaa; background: #fff; }   /* about 2.3:1 */',
  good='.hint { color: #595959; background: #fff; }   /* 7.0:1 */'),
 dict(id='AP-VIS-02', title='Links in text marked by colour only', sev='major', wcag=['1.4.1'], rgaa=['10.6'], axe=['link-in-text-block'], lang='css',
  what='With the underline removed, a link inside a paragraph differs from the words around it by its hue alone. People who do not perceive that hue cannot find the links.',
  dtext='a rule that removes the underline of all links. Fine for links in a navigation bar or a button-like component; a defect for links inside running text unless another non-colour cue exists.',
  detect=[R(r'''(?:^|[\s,}])a(?::(?:link|visited))?\s*\{[^}]*text-decoration\s*:\s*none''', target='css')],
  bad='a { color: #0b5fff; text-decoration: none; }',
  good='main a { text-decoration: underline; text-underline-offset: 0.15em; }'),
 dict(id='AP-VIS-03', title='Status conveyed by colour only', sev='major', wcag=['1.4.1'], rgaa=['3.1'], axe=[], lang='html',
  what='A green or red dot, a coloured row, a coloured chart series: the information does not exist for a screen reader and is ambiguous for people who do not distinguish the colours.',
  dtext='an empty element whose class combines a status word and a colour or state name. Other cases (rows, charts, required fields) need a person.',
  detect=[R(r'''<(?:span|i|div)\b(?![^>]*aria-hidden)[^>]*\bclass\s*=\s*['"][^'"]*\b(?:dot|badge|status|indicator|pill)\b[^'"]*(?:red|green|orange|yellow|success|danger|warning)[^'"]*['"][^>]*>\s*</(?:span|i|div)>''')],
  bad='<td><span class="status-dot status-green"></span></td>',
  good='<td><span class="status-dot status-green" aria-hidden="true"></span> In stock</td>'),
 dict(id='AP-VIS-04', title='Low-contrast boundary of a form control', sev='major', wcag=['1.4.11'], rgaa=['3.3'], axe=[], lang='css',
  what='A field drawn with a very light border on a white page cannot be located by people with low vision: they do not see where to click or type. The same goes for checkbox outlines, toggles and custom focus rings.',
  dtext='computed contrast under 3:1 between the visual boundary of a control and what surrounds it. The regular expression only flags common very light greys used as border colours.',
  detect=[X('For inputs, selects, textareas, checkboxes, radios and custom controls: contrast of the border (or of the fill, when it is what delimits the control) against the adjacent background under 3:1.'),
          R(r'''border(?:-color)?\s*:[^;}]*#(?:ccc|ddd|eee|cccccc|dddddd|eeeeee|e5e7eb|d1d5db|e0e0e0)\b''', target='css')],
  bad='input { border: 1px solid #ddd; background: #fff; }',
  good='input { border: 2px solid #6b6b6b; background: #fff; }   /* about 5.3:1 */'),
 dict(id='AP-VIS-05', title='Text container that clips its content', sev='major', wcag=['1.4.4', '1.4.12'], rgaa=['10.4', '10.12'], axe=[], lang='css',
  what='A fixed height with `overflow: hidden`, a line clamp or an ellipsis works for the designer\'s text at the designer\'s size. With larger text or wider spacing, the end of the text is cut off with no way to read it.',
  dtext='a rule that combines a fixed `height` with `overflow: hidden`, or uses `-webkit-line-clamp` or `text-overflow: ellipsis`. A defect when the hidden text is not available otherwise. Rules of the visually-hidden technique (1px size with `clip` or `clip-path`) are excluded.',
  detect=[R(r'''\{(?![^}]*(?:clip\s*:|clip-path\s*:|(?<![-\w])height\s*:\s*1px))[^}]*(?:(?<![-\w])height\s*:\s*\d+(?:\.\d+)?(?:px|rem|em)[^}]*overflow(?:-y)?\s*:\s*hidden|overflow(?:-y)?\s*:\s*hidden[^}]*(?<![-\w])height\s*:\s*\d+(?:\.\d+)?(?:px|rem|em)|-webkit-line-clamp\s*:\s*\d|text-overflow\s*:\s*ellipsis)''', target='css')],
  bad='.card-title { height: 48px; overflow: hidden; }',
  good='.card-title { min-height: 3rem; }'),
 dict(id='AP-VIS-06', title='Fixed widths that prevent reflow', sev='major', wcag=['1.4.10'], rgaa=['10.11'], axe=[], lang='css',
  what='A container with a width in pixels forces horizontal scrolling on a narrow screen and at high zoom. People who enlarge the page must scroll sideways for every line.',
  dtext='a `width` or `min-width` declaration of 400 pixels or more. Confirm at 320 CSS pixels wide; data tables, maps and diagrams may scroll inside their own container.',
  detect=[R(r'''[{;]\s*(?:min-)?width\s*:\s*(?:[4-9]\d{2}|\d{4,})px''', target='css')],
  bad='.container { width: 1200px; }',
  good='.container { width: 100%; max-width: 75rem; margin-inline: auto; }'),
 dict(id='AP-VIS-07', title='Text delivered as an image', sev='major', wcag=['1.4.5'], rgaa=['1.8'], axe=[], lang='html',
  what='A slogan, a promotional banner or a heading saved as a picture blurs when enlarged, does not reflow, ignores the colours and fonts the person has set, and often has an alternative that omits part of the text.',
  dtext='an image whose file name suggests text. Only a person can tell whether an image contains text that could have been real text. Logos are exempt.',
  detect=[R(r'''<img\b[^>]*\bsrc\s*=\s*['"][^'"]*(?:banner|headline|heading|slogan|promo|title|text)[^'"]*\.(?:png|jpe?g|gif|webp)['"]''')],
  bad='<img src="/img/promo-banner.png" alt="Summer sale">',
  good='<div class="promo">\n  <p class="promo-title">Summer sale</p>\n  <p>20 % off all bikes until 31 July, with the code SUMMER.</p>\n</div>'),
 dict(id='AP-VIS-08', title='Font sizes set in pixels', sev='minor', wcag=[], rgaa=[], axe=[], lang='css',
  what='Browser zoom still enlarges pixel sizes, so this is not a failure of the zoom criteria. It does ignore the default font size that some people set in their browser so as not to zoom every site by hand.',
  dtext='`font-size` in `px`.',
  detect=[R(r'''font-size\s*:\s*\d+(?:\.\d+)?px''', target='css')],
  bad='body { font-size: 14px; }',
  good='body { font-size: 100%; }\n.small-print { font-size: 0.875rem; }'),
 dict(id='AP-VIS-09', title='Orientation locked', sev='major', wcag=['1.3.4'], rgaa=['13.9'], axe=['css-orientation-lock'], lang='js',
  what='Some people use a phone or tablet fixed to a wheelchair or a stand and cannot turn it. A page that insists on portrait or landscape is unusable for them.',
  dtext='a call to the orientation lock API, or a media query on orientation that hides or rotates content.',
  detect=[R(r'''screen\.orientation\.lock\s*\(''', target='js'),
          R(r'''@media[^{]*orientation\s*:\s*(?:portrait|landscape)[^{]*\{[^}]*\{[^}]*(?:display\s*:\s*none|transform\s*:\s*rotate)''', target='css', flags='is', test=False)],
  bad="screen.orientation.lock('portrait');",
  good='// No lock: the layout adapts to both orientations with CSS.'),
]

MEDIA = [
 dict(id='AP-MED-01', title='Video without a captions track', sev='blocking', wcag=['1.2.2'], rgaa=['4.3'], axe=['video-caption'], lang='html',
  what='Everything said in the video is lost for people who cannot hear it. Auto-generated captions that nobody corrected do not solve this: names, figures and technical terms come out wrong.',
  dtext='a `<video>` with no `<track kind="captions">` or `kind="subtitles"`. Not a defect if the video has no speech or meaningful sound, or if captions are burned into the image; the quality of captions needs a person.',
  detect=[S('video:not(:has(track[kind="captions"], track[kind="subtitles"]))'),
          R(r'''<video\b[^>]*>(?:(?!</video>|<track\b[^>]*\bkind\s*=\s*['"](?:captions|subtitles)['"]).)*</video>''', flags='is')],
  bad='<video src="/media/tutorial.mp4" controls></video>',
  good='<video controls>\n  <source src="/media/tutorial.mp4" type="video/mp4">\n  <track kind="captions" src="/media/tutorial.en.vtt" srclang="en" label="English">\n</video>'),
 dict(id='AP-MED-02', title='Audio or video with no transcript or description', sev='major', wcag=['1.2.1', '1.2.5'], rgaa=['4.1', '4.5'], axe=[], lang='html',
  what='A podcast with no transcript does not exist for people who cannot hear it. A video whose images show what the voice does not say (a figure on screen, a demonstration) loses that part for people who cannot see it.',
  dtext='presence of `<audio>` or `<video>`. Then check by hand that a transcript is on the page or one link away, and whether an audio description is needed.',
  detect=[R(r'''<(?:audio|video)\b''')],
  bad='<audio src="/media/episode-12.mp3" controls></audio>',
  good='<h3 id="ep12">Episode 12: repairing a puncture</h3>\n<audio src="/media/episode-12.mp3" controls aria-labelledby="ep12"></audio>\n<p><a href="/podcast/episode-12/transcript">Transcript of episode 12</a></p>'),
 dict(id='AP-MED-03', title='Sound that starts by itself', sev='blocking', wcag=['1.4.2'], rgaa=['4.10'], axe=['no-autoplay-audio'], conf='certain', lang='html',
  what='Autoplaying sound covers the voice of the screen reader. The person cannot hear the page well enough to find the control that would stop it.',
  dtext='`autoplay` on an `<audio>`, or on a `<video>` without `muted`; an embedded player URL with `autoplay=1` and no mute parameter.',
  detect=[S('audio[autoplay], video[autoplay]:not([muted])'),
          R(r'''<audio\b[^>]*\sautoplay\b|<video\b(?![^>]*\smuted\b)[^>]*\sautoplay\b|<iframe\b[^>]*\bsrc\s*=\s*['"](?![^'"]*mute=1)[^'"]*autoplay=1''')],
  bad='<video src="/media/promo.mp4" autoplay loop></video>',
  good='<video controls preload="metadata">\n  <source src="/media/promo.mp4" type="video/mp4">\n  <track kind="captions" src="/media/promo.en.vtt" srclang="en" label="English">\n</video>'),
 dict(id='AP-MED-04', title='Media without controls', sev='major', wcag=['2.1.1', '2.2.2'], rgaa=['4.11', '13.8'], axe=[], lang='html',
  what='A background video or an audio clip with no controls cannot be paused. Moving images next to text prevent some people from reading, and nothing can be stopped with the keyboard.',
  dtext='`<video>` or `<audio>` without the `controls` attribute. Fine when a custom, keyboard-operable control set exists; check it by hand.',
  detect=[R(r'''<(?:video|audio)\b(?![^>]*\scontrols\b)[^>]*>''')],
  bad='<video src="/media/background.mp4" autoplay muted loop></video>',
  good='<video id="hero-video" src="/media/background.mp4" muted loop controls></video>'),
 dict(id='AP-MED-05', title='Content that moves by itself with no pause', sev='major', wcag=['2.2.2'], rgaa=['13.8'], axe=['marquee', 'blink'], lang='js',
  what='An auto-rotating carousel, a ticker or an endless animation next to text makes reading impossible for people with attention disorders, and moves content away before slow readers or screen reader users reach it.',
  dtext='an infinite CSS animation, a carousel configured with autoplay, or a timer that advances slides. A defect when the motion lasts more than 5 seconds and no pause, stop or hide control exists.',
  detect=[R(r'''\bautoplay\s*:\s*(?:true|\{)|data-(?:bs-)?ride\s*=\s*['"]carousel['"]|setInterval\s*\((?:(?!setInterval).){0,120}?(?:slide|next|rotate|carousel)''', target='js', flags='is'),
          R(r'''animation(?:-iteration-count)?\s*:[^;}]*\binfinite\b''', target='css', test=False)],
  bad="new Swiper('.hero', { loop: true, autoplay: { delay: 3000 } });",
  good="// No automatic rotation: previous and next buttons only (components/carousel.md).\nnew Swiper('.hero', { loop: true, navigation: { prevEl: '.hero-prev', nextEl: '.hero-next' } });"),
 dict(id='AP-MED-06', title='Animation that ignores the reduced-motion setting', sev='minor', wcag=[], rgaa=[], axe=[], lang='css',
  what='Parallax, zooming transitions and smooth scrolling cause dizziness and nausea for people with vestibular disorders. They ask their system for less motion; a page that does not listen gives them no way out.',
  dtext='keyframe animations, transform transitions or smooth scrolling in a style sheet that contains no `prefers-reduced-motion` media query.',
  detect=[R(r'''scroll-behavior\s*:\s*smooth|@keyframes\b|transition\s*:[^;}]*\b(?:transform|all)\b''', target='css', unless=r'''prefers-reduced-motion''')],
  bad='html { scroll-behavior: smooth; }\n.card { transition: transform 0.4s; }\n.card:hover { transform: scale(1.08); }',
  good='@media (prefers-reduced-motion: no-preference) {\n  html { scroll-behavior: smooth; }\n  .card { transition: transform 0.4s; }\n  .card:hover { transform: scale(1.08); }\n}'),
 dict(id='AP-MED-07', title='Flashing content', sev='blocking', wcag=['2.3.1'], rgaa=['13.7'], axe=['blink'], lang='css',
  what='Content that flashes more than three times per second can trigger a seizure in people with photosensitive epilepsy. This is the one defect in this catalogue that can injure.',
  dtext='an infinite animation with a period of about a third of a second or less, or a `<blink>` element. Video and animated images need to be watched by a person.',
  detect=[R(r'''animation\s*:[^;}]*(?<![\d.])0?\.[0-3]\d*s\b[^;}]*\binfinite\b|animation\s*:[^;}]*\binfinite\b[^;}]*(?<![\d.])0?\.[0-3]\d*s\b|<blink\b''', target='css')],
  bad='.alert { animation: flash 0.2s infinite; }',
  good='.alert { border: 3px solid currentColor; font-weight: 700; }   /* draws attention without flashing */'),
]

DYNAMIC = [
 dict(id='AP-DYN-01', title='Status message with no live region', sev='major', wcag=['4.1.3'], rgaa=['7.5'], axe=[], lang='html',
  what='"Saved", "3 results", "Payment refused" appear on screen, and a screen reader says nothing, because focus is elsewhere and nothing marks the message as an update.',
  dtext='an element whose class or id suggests a notification and that has no `role="status"`, `role="alert"`, `role="log"` or `aria-live`. Also check loading indicators and result counts.',
  detect=[R(r'''<(?:div|p|span)\b(?![^>]*(?:\brole\s*=\s*['"](?:status|alert|log)['"]|aria-live))[^>]*\b(?:class|id)\s*=\s*['"][^'"]*\b(?:toast|snackbar|notification|flash|alert|feedback)\b''')],
  bad='<div class="toast">Your changes are saved</div>',
  good='<!-- present and empty at page load; the message is written into it later -->\n<div class="toast" role="status"></div>'),
 dict(id='AP-DYN-02', title='Message that disappears on a timer', sev='major', wcag=['2.2.1'], rgaa=['13.1'], axe=[], lang='js',
  what='A toast that leaves after three seconds is gone before a slow reader finishes it, before a magnifier user finds it, or while the screen reader is still speaking something else. If it carried an "Undo" link, the action is lost too.',
  dtext='a timer that removes or hides a notification. Acceptable only for messages that repeat information visible elsewhere.',
  detect=[R(r'''setTimeout\s*\((?:(?!setTimeout).){0,200}?(?:toast|snackbar|notification|alert|message)(?:(?!setTimeout).){0,200}?(?:remove|hide|close|dismiss)''', target='js', flags='is')],
  bad="showToast('Message archived. Undo');\nsetTimeout(() => toast.remove(), 3000);",
  good="// The message stays until the person closes it (components/status-messages.md).\nshowToast('Message archived.');"),
 dict(id='AP-DYN-03', title='Client-side navigation that changes neither title nor focus', sev='major', wcag=['2.4.2'], rgaa=['8.6'], axe=[], lang='js',
  what='After a link is activated in a single-page application, nothing is announced: the title is the old one and focus is still on the link in the menu. A screen reader user cannot tell that the page changed.',
  dtext='use of the History API in a script that never sets `document.title`. Moving focus to the new content is a good practice to check by hand.',
  detect=[R(r'''history\.pushState\s*\(''', target='js', unless=r'''document\.title\s*=''')],
  bad="history.pushState({}, '', '/orders');\nrenderOrders();",
  good="history.pushState({}, '', '/orders');\nrenderOrders();\ndocument.title = 'Your orders - Colibri bookshop';\ndocument.querySelector('main h1').focus();   // the h1 has tabindex=\"-1\""),
 dict(id='AP-DYN-04', title='Everything announced as an alert', sev='minor', wcag=[], rgaa=[], axe=[], lang='html',
  what='`role="alert"` and `aria-live="assertive"` interrupt whatever the screen reader is saying. Used for routine confirmations, they cut speech constantly and teach people to ignore real alerts.',
  dtext='`aria-live="assertive"`, or `role="alert"` on messages that are not errors or urgent warnings.',
  detect=[R(r'''aria-live\s*=\s*['"]assertive['"]''')],
  bad='<div aria-live="assertive">Item added to your basket</div>',
  good='<div role="status">Item added to your basket</div>'),
 dict(id='AP-DYN-05', title='Change of context on focus or without request', sev='major', wcag=['3.2.1'], rgaa=['7.4', '13.2'], axe=[], lang='html',
  what='A page that navigates, submits or opens a window when a field merely receives focus, or by itself on load, moves people who did nothing. Screen reader and magnifier users may not notice and lose their bearings.',
  dtext='a `focus` handler that navigates, submits or opens a window; a call to `window.open` outside a click handler.',
  detect=[R(r'''\bonfocus\s*=\s*['"][^'"]*(?:location|submit\s*\(|window\.open)'''),
          R(r'''window\.open\s*\(''', target='js', test=False)],
  bad='<input name="promo" onfocus="window.open(\'/offers\')">',
  good='<label for="promo">Promotional code</label>\n<input id="promo" name="promo">\n<a href="/offers">See current offers</a>'),
]
